SELECT info.FINPROD_MARKET_ID prodid, info.FINPROD_NAME prodname, plan.OPEN_DATE_STR openstart, plan.OPEN_DATE_END openend, plan.OPEN_VDATE openvdate, plan.OPEN_TYPE plantype, ifnull(plan.UPDATE_TIME,plan.CREATE_TIME) updatetime FROM FIN_PRODUCT info,FIN_OPEN_PLAN plan WHERE info.FINPROD_ID = plan.FINPROD_ID and info.FINPROD_TYPE2 = 'F16'
#{prodid,jdbcType=VARCHAR}
and plan.OPEN_TYPE in ('01','02')
and plan.OPEN_TYPE = #{plantype,jdbcType=VARCHAR}

select distinct info.FINPROD_MARKET_ID prodid FROM FIN_PRODUCT info,FIN_OPEN_PLAN plan WHERE info.FINPROD_ID = plan.FINPROD_ID and info.FINPROD_TYPE2 = 'F16' and ifnull(plan.UPDATE_TIME,plan.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
and info.FINPROD_MARKET_ID in
#{prodid,jdbcType=VARCHAR}
